<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{AdSlot,Site}; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class AdSlotController extends Controller { public function index(Request $r){$siteId=$r->integer('site_id')?:Site::value('id');$slots=AdSlot::with('site')->when($siteId,fn($q)=>$q->where('site_id',$siteId))->orderBy('key')->get();return view('admin.ads.index',['slots'=>$slots,'sites'=>Site::orderBy('name')->get(),'siteId'=>$siteId]);} public function edit(AdSlot $adSlot){return view('admin.ads.form',['slot'=>$adSlot,'sites'=>Site::orderBy('name')->get()]);} public function update(Request $r,AdSlot $adSlot){$d=$r->validate(['label'=>'required|string|max:255','ad_unit_path'=>'nullable|string|max:500','sizes_text'=>'nullable|string|max:1000','type'=>['required',Rule::in(['display','anchor','interstitial','rewarded'])],'enabled'=>'nullable|boolean']);$d['enabled']=$r->boolean('enabled');$d['sizes']=collect(preg_split('/[\s,]+/',$d['sizes_text']??'',-1,PREG_SPLIT_NO_EMPTY))->map(fn($x)=>trim($x))->values()->all();unset($d['sizes_text']);$adSlot->update($d);return back()->with('ok','Ad slot saved.');} }
